import fs from 'node:fs';import vm from 'node:vm';import assert from 'node:assert/strict';
const ctx={};vm.createContext(ctx);for(const f of ['learning-engine-20261030.js','next-learning-core-20261030.js','learning-catalogue-20261030.js',...Array.from({length:16},(_,i)=>'learning-chapter-'+String(i+1).padStart(2,'0')+'-20261030.js')])vm.runInContext(fs.readFileSync('students/'+f,'utf8'),ctx);const L=ctx.MT_NEXT_LEARNING,bank=Object.values(ctx.MT_LEARNING_CHAPTERS).flatMap(c=>c.questions);let checks=0;
function near(a,b){assert.ok(Math.abs(a-b)<=1e-8*Math.max(1,Math.abs(b)),a+' ≠ '+b);checks++;}
class Storage{constructor(){this.values=new Map();}getItem(k){return this.values.get(k)??null;}setItem(k,v){this.values.set(k,v);}}
assert.equal(bank.length,292);checks++;
for(let chapter=1;chapter<=16;chapter++)for(const seed of [0,1,17,413,2147483647]){const q=L.variant(chapter,seed),p=q.params;assert.equal(JSON.stringify(q),JSON.stringify(L.variant(chapter,seed)));assert.ok(q.work.length>0&&q.work.every(s=>Number.isFinite(s.expected)));checks+=2;switch(chapter){case 1:near(q.expected*10000,p.a*p.b);break;case 2:near(q.expected*p.volume,p.mass);break;case 3:near(q.expected/1000,p.alpha*1e-6*p.length*p.delta);break;case 4:near(q.expected*p.z2,-p.rpm*p.z1);break;case 5:near(q.expected/p.concentration,p.volume/1000);break;case 6:{const current=p.voltage/(p.r1+p.r2);near(q.expected,current*current*p.r1+current*current*p.r2);break;}case 7:near((2*Math.PI*q.expected)**2*(p.l/1000)*(p.cap/1e6),1);break;case 8:near(q.expected/p.supply,p.duty);break;case 9:near(q.expected/p.efficiency/p.lhv/1000*3600,p.flow);break;case 10:near(q.expected/p.flow+p.h2,p.h1);break;case 11:near(q.expected*p.flow/60,p.volume);break;case 12:near(q.expected-p.cooling,p.power);break;case 13:near(q.expected*p.speed,p.distance);break;case 14:near(q.expected/p.volume,p.density);break;case 15:near(q.expected*(1+p.rate)**p.years,p.future);break;case 16:near(q.expected-p.initial,p.loaded-p.discharged);break;}}
let time=1000000;const storage=new Storage(),engine=L.create(storage,()=>time),q=bank.find(q=>q.chapter===1);engine.record(q,{valid:true,correct:true},String(q.expected));assert.equal(engine.due().length,0);checks++;time+=86400000;assert.equal(engine.due().length,1);checks++;engine.record(q,{valid:true,correct:false,message:'Check the unit conversions.'},'1');assert.equal(engine.data.events[0].category,'units');checks++;assert.equal(engine.due().length,0);time+=600000;assert.equal(engine.due().length,1);checks+=2;engine.setDraft(q.id,{answer:'unfinished',working:['3'],formula:'A = ab',unit:'m²'});assert.equal(L.create(storage,()=>time).draft(q.id).answer,'unfinished');checks++;assert.throws(()=>engine.setDraft('__proto__',{}));checks++;
const test=engine.startTest({bank,chapters:[1,2],weights:{1:10,2:0},count:5,minutes:1,resources:false,seed:17});assert.ok(test.items.every(q=>q.chapter===1));assert.equal(new Set(test.items.map(q=>q.id)).size,5);checks+=2;engine.answerTest(test.items[0].id,String(test.items[0].expected));const restored=L.create(storage,()=>time);assert.equal(restored.remaining(),60000);checks++;time+=61000;assert.equal(restored.remaining(),0);assert.throws(()=>restored.answerTest(test.items[1].id,'1'));checks+=2;const result=restored.submitTest();assert.equal(result.score,1);assert.equal(result.grades.length,5);checks+=2;test.items[0].expected=123456;assert.equal(restored.data.tests[0].score,1);checks++;
for(const minutes of [20,45,90]){const plan=L.teachingPlan(1,minutes,bank,[]);assert.equal(plan.stages.reduce((n,s)=>n+s.minutes,0),minutes);assert.ok(plan.questions.length>0&&plan.teacherGuide.length>0);checks+=2;}
for(const path of L.paths){assert.ok(path.chapters.length>1&&path.chapters.every(c=>c>=1&&c<=16));checks++;}assert.equal(Object.keys(L.concepts).length,16);checks++;
for(const raw of ['{"version":2,"important":"keep"}','not JSON']){const s=new Storage();s.setItem(L.key,raw);const e=L.create(s,()=>time);assert.throws(()=>e.record(q,{valid:true,correct:true},'0'));assert.equal(s.getItem(L.key),raw);checks+=2;}
assert.throws(()=>L.variant(0,17));assert.throws(()=>L.variant(1,-1));checks+=2;
console.log(JSON.stringify({status:'PASS',checks,variantCases:80,chapters:16,paths:L.paths.length,scope:'Deterministic variants with independent inverse/energy identities, retrieval scheduling, mistake classification, drafts, weighted timed tests, frozen history, teaching plans and format protection.'}));
